#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin>>n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> rawCells(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>ksz[i];
        rawCells[i].resize(ksz[i]);
        for(int j=0;j<ksz[i];j++) cin>>rawCells[i][j].first>>rawCells[i][j].second;
        totalCells+=ksz[i];
    }

    // Transform: first flip (f=1 means x->-x), then rotate r times 90° CCW
    // CCW rotation: (x,y) -> (-y,x)
    auto transform=[&](vector<pair<int,int>>& cells, int r, int f, vector<pair<int,int>>& out){
        out.resize(cells.size());
        for(int j=0;j<(int)cells.size();j++){
            int x=cells[j].first, y=cells[j].second;
            if(f) x=-x;
            for(int rr=0;rr<r;rr++){int nx=-y,ny=x;x=nx;y=ny;}
            out[j]={x,y};
        }
        int mx=INT_MAX,my=INT_MAX;
        for(auto&[x,y]:out){mx=min(mx,x);my=min(my,y);}
        for(auto&[x,y]:out){x-=mx;y-=my;}
    };

    struct Orient{vector<pair<int,int>> cells;int w,h,r,f;};
    vector<vector<Orient>> orients(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++) for(int r=0;r<4;r++){
            vector<pair<int,int>> tr;
            transform(rawCells[i],r,f,tr);
            sort(tr.begin(),tr.end());
            if(seen.insert(tr).second){
                int mw=0,mh=0;
                for(auto[x,y]:tr){mw=max(mw,x);mh=max(mh,y);}
                orients[i].push_back({tr,mw+1,mh+1,r,f});
            }
        }
    }

    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return ksz[a]>ksz[b];});

    int W0=max(1,(int)ceil(sqrt((double)totalCells)));
    int bestArea=INT_MAX;
    vector<int> bx(n),by(n),br(n),bf(n);
    int bestW=0,bestH=0;

    for(int tryW=max(1,W0-5);tryW<=W0+60&&tryW<=totalCells+5;tryW++){
        vector<int> height(tryW,0);
        vector<int> px(n),py(n),pr(n),pf(n);
        int maxH=0; bool ok=true;
        for(int idx=0;idx<n;idx++){
            int i=order[idx];
            int bs=INT_MAX,bxx=-1,byy=-1,boi=-1;
            for(int oi=0;oi<(int)orients[i].size();oi++){
                auto&o=orients[i][oi];
                if(o.w>tryW)continue;
                for(int x=0;x<=tryW-o.w;x++){
                    int y=0;
                    for(auto[cx,cy]:o.cells) y=max(y,height[x+cx]-cy);
                    int mH=max(maxH,y+o.h);
                    int sc=mH*100000+y*1000+x;
                    if(sc<bs){bs=sc;bxx=x;byy=y;boi=oi;}
                }
            }
            if(bxx<0){ok=false;break;}
            auto&o=orients[i][boi];
            px[i]=bxx;py[i]=byy;pr[i]=o.r;pf[i]=o.f;
            for(auto[cx,cy]:o.cells){height[bxx+cx]=max(height[bxx+cx],byy+cy+1);maxH=max(maxH,byy+cy+1);}
        }
        if(!ok)continue;
        int area=tryW*maxH;
        if(area<bestArea){bestArea=area;bestW=tryW;bestH=maxH;bx=px;by=py;br=pr;bf=pf;}
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bx[i]<<" "<<by[i]<<" "<<br[i]<<" "<<bf[i]<<"\n";
}
